examples.code:
const response = await fetch('http://localhost:8000/v1/skills/install', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ skill_name: 'code-review' })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/skills/install")
    .json(&serde_json::json!({ "skill_name": "code-review" }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

const response = await fetch('http://localhost:8000/v1/skills/remove', {
  method: 'DELETE',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ skill_name: 'code-review' })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.delete("http://localhost:8000/v1/skills/remove")
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);
